WITH filtered AS (SELECT *, stock_qty - cost AS stock_qty_minus_cost, CONCAT_WS('-', brand, product_name) AS brand_product_name_key FROM products WHERE launch_date >= DATE '2023-03-31' AND brand IS DISTINCT FROM 'Acme') SELECT id, product_name, category, brand, price, cost, stock_qty, tags, COUNT(cost) OVER (PARTITION BY category ORDER BY stock_qty_minus_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_cost, AVG(cost) OVER (PARTITION BY category ORDER BY stock_qty_minus_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_cost, MIN(cost) OVER (PARTITION BY category ORDER BY stock_qty_minus_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_cost, SUM(cost) OVER (PARTITION BY category ORDER BY stock_qty_minus_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_cost, NTILE(10) OVER (PARTITION BY brand ORDER BY stock_qty_minus_cost, id) AS stock_qty_minus_cost_bucket FROM filtered;
